{"@context": "https://schema.org", "@type": "DefinedTermSet", "name": "Термины: карточка образцов подписей для казначейства", "inLanguage": "ru-RU", "hasDefinedTerm": [{"@type": "DefinedTerm", "name": "Карточка образцов подписей", "description": "Документ с эталонными собственноручными подписями лиц, уполномоченных распоряжаться счётом; используется для сличения подписи на бумажном платёжном документе с образцом."}, {"@type": "DefinedTerm", "name": "Форма 0531753", "description": "Унифицированная форма карточки образцов подписей к лицевым счетам — приложение № 2 к приказу Казначейства России от 17.10.2016 № 21н."}, {"@type": "DefinedTerm", "name": "Приказ № 21н", "description": "Приказ Казначейства России от 17.10.2016 № 21н о порядке открытия и ведения лицевых счетов ТОФК; регулирует счета участников бюджетного процесса, бюджетных и автономных учреждений."}, {"@type": "DefinedTerm", "name": "ТОФК", "description": "Территориальный орган Федерального казначейства — управление, которое открывает и ведёт лицевые счета и принимает карточку образцов подписей."}, {"@type": "DefinedTerm", "name": "Лицевой счёт участника казначейского сопровождения", "description": "Счёт с кодом 71, открываемый исполнителям контрактов при казначейском сопровождении по приказам Федерального казначейства № 44н и № 22н — в электронном порядке, без бумажной карточки в общем случае."}, {"@type": "DefinedTerm", "name": "УКЭП", "description": "Усиленная квалифицированная электронная подпись; в электронном документообороте с казначейством заменяет собственноручный росчерк — подлинность проверяется криптографически."}, {"@type": "DefinedTerm", "name": "Машиночитаемая доверенность (МЧД)", "description": "Электронная доверенность в машиночитаемом формате, подтверждающая полномочия представителя организации при подписании документов УКЭП."}, {"@type": "DefinedTerm", "name": "Право первой и второй подписи", "description": "Конструкция карточки 0531753: первая подпись — руководитель и уполномоченные им лица, вторая — главный бухгалтер и уполномоченные; в банковской практике по Инструкции № 204-И понятие первой подписи больше не используется."}]}
